import {
  type ApiRequest,
  type ApiResponse,
  type Context,
  getContext,
} from "iii-sdk";
import { iii } from "./iii.js";

export const useApi = <TBody = unknown>(
  config: {
    api_path: string;
    http_method: string;
    description?: string;
    metadata?: Record<string, unknown>;
  },
  handler: (req: ApiRequest<TBody>, context: Context) => Promise<ApiResponse>,
) => {
  const function_id = `api::${config.http_method.toLowerCase()}::${config.api_path}`;

  iii.registerFunction({ id: function_id, metadata: config.metadata }, (req) =>
    handler(req as ApiRequest<TBody>, getContext()),
  );

  iii.registerTrigger({
    type: "http",
    function_id,
    config: {
      api_path: config.api_path,
      http_method: config.http_method,
      description: config.description,
      metadata: config.metadata,
    },
  });
};

let eventCounter = 0;

export const useEvent = <TData = unknown>(
  topic: string,
  handler: (data: TData, ctx: Context) => Promise<void>,
  description?: string,
) => {
  const function_id = `event::${topic}::handler::${++eventCounter}`;

  iii.registerFunction({ id: function_id, description }, (data) =>
    handler(data as TData, getContext()),
  );

  iii.registerTrigger({
    type: "subscribe",
    function_id,
    config: { topic },
  });
};

export const emit = async <TData = unknown>(
  topic: string,
  data: TData,
): Promise<void> => {
  iii.triggerVoid("publish", { topic, data });
};

export const useCron = (
  expression: string,
  handler: (ctx: Context) => Promise<void>,
  description?: string,
) => {
  const sanitized = expression.replace(/\s+/g, "_").replace(/\*/g, "x");
  const function_id = `cron::${sanitized}::${Date.now()}`;

  iii.registerFunction({ id: function_id, description }, () =>
    handler(getContext()),
  );

  iii.registerTrigger({
    type: "cron",
    function_id,
    config: { expression },
  });
};

import { Logger } from "iii-sdk";
import { state } from "./state.js";

const logger = new Logger(undefined, "tailclaude-traces");

const SCOPE = "traces";
const MAX_AGE_MS = 30 * 24 * 60 * 60 * 1000;

export interface TraceRecord {
  _key: string;
  requestId: string;
  sessionId?: string | null;
  model?: string;
  cost: number;
  inputTokens: number;
  outputTokens: number;
  duration: number;
  exitCode?: number | null;
  reason?: string;
  timestamp: string;
}

export async function writeCompletedTrace(data: {
  requestId: string;
  sessionId: string | null;
  model: string;
  cost: number;
  inputTokens: number;
  outputTokens: number;
  duration: number;
  exitCode?: number | null;
}): Promise<void> {
  try {
    await state.set({
      scope: SCOPE,
      key: data.requestId,
      data: {
        _key: data.requestId,
        requestId: data.requestId,
        sessionId: data.sessionId,
        model: data.model,
        cost: data.cost,
        inputTokens: data.inputTokens,
        outputTokens: data.outputTokens,
        duration: data.duration,
        exitCode: data.exitCode ?? null,
        timestamp: new Date().toISOString(),
      } as TraceRecord,
    });
  } catch (e) {
    logger.error("Failed to write completed trace", {
      error: (e as Error)?.message,
    });
  }
}

export async function writeStoppedTrace(data: {
  requestId: string;
  reason: string;
}): Promise<void> {
  try {
    const existing = await state.get<TraceRecord>({
      scope: SCOPE,
      key: data.requestId,
    });
    if (existing) return;
    await state.set({
      scope: SCOPE,
      key: data.requestId,
      data: {
        _key: data.requestId,
        requestId: data.requestId,
        reason: data.reason,
        cost: 0,
        inputTokens: 0,
        outputTokens: 0,
        duration: 0,
        timestamp: new Date().toISOString(),
      } as TraceRecord,
    });
  } catch (e) {
    logger.error("Failed to write stopped trace", {
      error: (e as Error)?.message,
    });
  }
}

export async function getTraces(limit = 100): Promise<TraceRecord[]> {
  try {
    const all = await state.list<TraceRecord>({ scope: SCOPE });
    return all
      .sort((a, b) => b.timestamp.localeCompare(a.timestamp))
      .slice(0, limit);
  } catch {
    return [];
  }
}

export async function cleanupOldTraces(): Promise<number> {
  let removed = 0;
  try {
    const cutoff = Date.now() - MAX_AGE_MS;
    const all = await state.list<TraceRecord>({ scope: SCOPE });
    for (const trace of all) {
      if (new Date(trace.timestamp).getTime() < cutoff) {
        await state.delete({ scope: SCOPE, key: trace._key });
        removed++;
      }
    }
  } catch (e) {
    logger.error("Failed to cleanup old traces", {
      error: (e as Error)?.message,
    });
  }
  return removed;
}

import { Logger } from "iii-sdk";
import { state } from "./state.js";
import { getMetrics } from "./metrics.js";
import { emit } from "./hooks.js";
import { pushActivity } from "./activity.js";

const logger = new Logger(undefined, "tailclaude-metrics-timeline");

export const workerStartedAt = new Date().toISOString();

const SCOPE = "metrics_timeline";
const COOLDOWN_SCOPE = "alert_cooldowns";
const ALERTS_SCOPE = "alerts";
const MAX_SNAPSHOTS = 60;
const COOLDOWN_MS = 5 * 60 * 1000;

export interface MetricsSnapshot {
  _key: string;
  ts: string;
  memory_rss: number;
  cpu_percent: number;
  event_loop_lag_ms: number;
  active_chats: number;
}

interface AlertCooldown {
  lastFired: number;
}

interface AlertState {
  _key: string;
  active: boolean;
  value: number;
  threshold: number;
  timestamp: string;
}

const THRESHOLDS = {
  high_cpu: { metric: "cpu_percent" as const, threshold: 80 },
  high_memory: { metric: "memory_rss" as const, threshold: 500 * 1024 * 1024 },
  high_lag: { metric: "event_loop_lag_ms" as const, threshold: 100 },
  high_concurrency: { metric: "active_chats" as const, threshold: 3 },
};

async function getActiveChatCount(): Promise<number> {
  try {
    const chats = await state.list({ scope: "active_chats" });
    return chats.length;
  } catch {
    return 0;
  }
}

async function checkCooldown(alertType: string): Promise<boolean> {
  try {
    const cd = await state.get<AlertCooldown>({
      scope: COOLDOWN_SCOPE,
      key: alertType,
    });
    if (!cd) return true;
    return Date.now() - cd.lastFired > COOLDOWN_MS;
  } catch {
    return true;
  }
}

async function setCooldown(alertType: string): Promise<void> {
  try {
    await state.set({
      scope: COOLDOWN_SCOPE,
      key: alertType,
      data: { lastFired: Date.now() },
    });
  } catch {}
}

async function fireAlert(
  alertType: string,
  value: number,
  threshold: number,
): Promise<void> {
  const canFire = await checkCooldown(alertType);
  if (!canFire) return;

  await setCooldown(alertType);

  const timestamp = new Date().toISOString();
  try {
    await state.set({
      scope: ALERTS_SCOPE,
      key: alertType,
      data: {
        _key: alertType,
        active: true,
        value,
        threshold,
        timestamp,
      } as AlertState,
    });
  } catch {}

  const label = alertType.replace("_", " ").replace("high ", "High ");

  let unit: string;
  switch (alertType) {
    case "high_memory":
      unit = `${(value / (1024 * 1024)).toFixed(0)}MB`;
      break;
    case "high_lag":
      unit = `${value.toFixed(0)}ms`;
      break;
    case "high_concurrency":
      unit = `${value} active chats`;
      break;
    default:
      unit = `${value.toFixed(1)}%`;
  }

  let thresholdStr: string;
  switch (alertType) {
    case "high_memory":
      thresholdStr = `${(threshold / (1024 * 1024)).toFixed(0)}MB`;
      break;
    case "high_lag":
      thresholdStr = `${threshold}ms`;
      break;
    case "high_concurrency":
      thresholdStr = `${threshold}`;
      break;
    default:
      thresholdStr = `${threshold}%`;
  }

  pushActivity("alert", `${label}: ${unit} (threshold: ${thresholdStr})`, {
    alertType,
    value,
    threshold,
  });

  emit(`alert::${alertType}`, { value, threshold, timestamp }).catch(() => {});
  logger.warn("Alert fired", { alertType, value, threshold });
}

async function clearAlert(alertType: string): Promise<void> {
  try {
    const existing = await state.get<AlertState>({
      scope: ALERTS_SCOPE,
      key: alertType,
    });
    if (existing?.active) {
      await state.set({
        scope: ALERTS_SCOPE,
        key: alertType,
        data: {
          _key: alertType,
          active: false,
          value: 0,
          threshold: 0,
          timestamp: new Date().toISOString(),
        } as AlertState,
      });
    }
  } catch {}
}

export async function snapshotMetrics(): Promise<void> {
  const metrics = getMetrics();
  const activeChats = await getActiveChatCount();
  const ts = new Date().toISOString();
  const key = ts.replace(/[:.]/g, "-");

  const memRss = metrics.memory_rss ?? 0;
  const cpuPct = metrics.cpu_percent ?? 0;
  const lagMs = metrics.event_loop_lag_ms ?? 0;

  const snapshot: MetricsSnapshot = {
    _key: key,
    ts,
    memory_rss: memRss,
    cpu_percent: cpuPct,
    event_loop_lag_ms: lagMs,
    active_chats: activeChats,
  };

  try {
    await state.set({ scope: SCOPE, key, data: snapshot });
  } catch (e) {
    logger.error("Failed to save metrics snapshot", {
      error: (e as Error)?.message,
    });
  }

  try {
    const all = await state.list<MetricsSnapshot>({ scope: SCOPE });
    if (all.length > MAX_SNAPSHOTS) {
      const sorted = all.sort((a, b) => a.ts.localeCompare(b.ts));
      const toRemove = sorted.slice(0, all.length - MAX_SNAPSHOTS);
      for (const entry of toRemove) {
        await state.delete({ scope: SCOPE, key: entry._key });
      }
    }
  } catch {}

  const values: Record<string, number> = {
    cpu_percent: cpuPct,
    memory_rss: memRss,
    event_loop_lag_ms: lagMs,
    active_chats: activeChats,
  };

  for (const [alertType, config] of Object.entries(THRESHOLDS)) {
    const value = values[config.metric];
    if (value > config.threshold) {
      await fireAlert(alertType, value, config.threshold);
    } else {
      await clearAlert(alertType);
    }
  }
}

export async function getTimeline(): Promise<MetricsSnapshot[]> {
  try {
    const all = await state.list<MetricsSnapshot>({ scope: SCOPE });
    return all.sort((a, b) => a.ts.localeCompare(b.ts));
  } catch {
    return [];
  }
}

export async function getActiveAlerts(): Promise<
  Array<{ type: string } & AlertState>
> {
  try {
    const all = await state.list<AlertState>({ scope: ALERTS_SCOPE });
    return all
      .filter((a) => a.active)
      .map((a) => ({ ...a, type: a._key || "unknown" }));
  } catch {
    return [];
  }
}

import { WorkerMetricsCollector } from "iii-sdk/telemetry";

export const metricsCollector = new WorkerMetricsCollector();

let cachedMetrics: ReturnType<WorkerMetricsCollector["collect"]> | null = null;
let cacheTimestamp = 0;
const CACHE_TTL = 5000;

export function getMetrics(): ReturnType<WorkerMetricsCollector["collect"]> {
  const now = Date.now();
  if (!cachedMetrics || now - cacheTimestamp > CACHE_TTL) {
    cachedMetrics = metricsCollector.collect();
    cacheTimestamp = now;
  }
  return cachedMetrics;
}

import {
  readdirSync,
  statSync,
  openSync,
  readSync,
  closeSync,
  existsSync,
} from "node:fs";
import { join, basename } from "node:path";
import { homedir } from "node:os";
import { state } from "./state.js";
import { emit } from "./hooks.js";

const PROJECTS_DIR = join(homedir(), ".claude", "projects");

export interface SessionIndexEntry {
  id: string;
  slug?: string;
  project?: string;
  cwd?: string;
  messageCount: number;
  lastModified: string;
  filePath: string;
}

let indexing = false;

export async function indexSessions(): Promise<number> {
  if (indexing) return 0;
  indexing = true;
  try {
    return await doIndexSessions();
  } finally {
    indexing = false;
  }
}

async function doIndexSessions(): Promise<number> {
  const entries: SessionIndexEntry[] = [];

  try {
    const projects = readdirSync(PROJECTS_DIR, { withFileTypes: true });
    for (const projEntry of projects) {
      if (!projEntry.isDirectory()) continue;

      const projDir = join(PROJECTS_DIR, projEntry.name);
      const projectName = extractProjectName(projEntry.name);

      try {
        const files = readdirSync(projDir);
        const jsonlFiles = files.filter(
          (f) => f.endsWith(".jsonl") && !f.includes("memory"),
        );

        for (const file of jsonlFiles) {
          const filePath = join(projDir, file);
          try {
            const stat = statSync(filePath);
            if (stat.size < 50) continue;
            const sessionId = file.replace(".jsonl", "");

            let project: string | undefined = projectName;
            let messageCount = 0;
            let slug: string | undefined;
            let cwd: string | undefined;

            const fd = openSync(filePath, "r");
            let head: string;
            try {
              const buf = Buffer.alloc(8192);
              const bytesRead = readSync(fd, buf, 0, 8192, 0);
              head = buf.toString("utf-8", 0, bytesRead);
            } finally {
              closeSync(fd);
            }
            const lines = head.split("\n").filter((l: string) => l.trim());

            for (const line of lines) {
              try {
                const parsed = JSON.parse(line);
                if (parsed.cwd && !cwd) {
                  cwd = parsed.cwd;
                  if (!project) project = basename(parsed.cwd) || project;
                }
                if (parsed.slug && !slug) slug = parsed.slug;
                const role = parsed.message?.role;
                if (role === "user" || role === "assistant") messageCount++;
              } catch {
                // skip
              }
            }

            entries.push({
              id: sessionId,
              slug,
              project,
              cwd,
              messageCount: messageCount || 0,
              lastModified: stat.mtime.toISOString(),
              filePath,
            });
          } catch {
            // skip unreadable files
          }
        }
      } catch {
        // skip unreadable project dirs
      }
    }
  } catch {
    // projects directory doesn't exist
  }

  let added = 0;
  for (const entry of entries) {
    try {
      const existing = await state.get<SessionIndexEntry>({
        scope: "session_index",
        key: entry.id,
      });
      await state.set({
        scope: "session_index",
        key: entry.id,
        data: entry,
      });
      if (!existing) added++;
    } catch {
      // continue persisting remaining entries
    }
  }

  await emit("session::indexed", {
    total: entries.length,
    added,
  }).catch(() => {});

  return entries.length;
}

export async function getSessionIndex(): Promise<SessionIndexEntry[]> {
  try {
    const sessions = await state.list<SessionIndexEntry>({
      scope: "session_index",
    });
    return sessions.sort(
      (a, b) =>
        new Date(b.lastModified).getTime() - new Date(a.lastModified).getTime(),
    );
  } catch {
    return [];
  }
}

export async function getSessionFilePath(
  sessionId: string,
): Promise<string | null> {
  try {
    const entry = await state.get<SessionIndexEntry>({
      scope: "session_index",
      key: sessionId,
    });
    return entry?.filePath ?? null;
  } catch {
    return null;
  }
}

export async function cleanStaleSessionIndex(): Promise<number> {
  let removed = 0;
  try {
    const sessions = await state.list<SessionIndexEntry>({
      scope: "session_index",
    });
    for (const session of sessions) {
      if (!existsSync(session.filePath)) {
        await state.delete({ scope: "session_index", key: session.id });
        removed++;
      }
    }
  } catch {
    // state unavailable
  }
  return removed;
}

function extractProjectName(dirName: string): string {
  const cleaned = dirName.replace(/^-/, "");
  const parts = cleaned.split("-");
  if (parts.length <= 2) return parts.pop() || dirName;
  const meaningful = parts.filter(
    (p) => p !== "Users" && p !== "private" && p !== "tmp" && p.length > 1,
  );
  return meaningful.pop() || parts.pop() || dirName;
}

import { Logger } from "iii-sdk";
import { state } from "./state.js";

const logger = new Logger(undefined, "tailclaude-usage");

const SCOPE = "usage_daily";
const MAX_DAYS = 30;

export interface DailyUsage {
  _key: string;
  date: string;
  requestCount: number;
  totalCost: number;
  totalInputTokens: number;
  totalOutputTokens: number;
}

function todayKey(): string {
  return new Date().toISOString().slice(0, 10);
}

export async function incrementUsage(
  cost: number,
  inputTokens: number,
  outputTokens: number,
): Promise<void> {
  const today = todayKey();

  try {
    const updated = await state.update({
      scope: SCOPE,
      key: today,
      ops: [
        { type: "increment", path: "requestCount", by: 1 },
        { type: "increment", path: "totalCost", by: cost },
        { type: "increment", path: "totalInputTokens", by: inputTokens },
        { type: "increment", path: "totalOutputTokens", by: outputTokens },
      ],
    });

    if (!updated) {
      await state.set({
        scope: SCOPE,
        key: today,
        data: {
          _key: today,
          date: today,
          requestCount: 1,
          totalCost: cost,
          totalInputTokens: inputTokens,
          totalOutputTokens: outputTokens,
        } as DailyUsage,
      });
    }
  } catch (e) {
    logger.error("Failed to increment usage", {
      error: (e as Error)?.message,
    });
  }
}

export async function getUsageStats(days = 7): Promise<DailyUsage[]> {
  try {
    const all = await state.list<DailyUsage>({ scope: SCOPE });
    return all.sort((a, b) => b.date.localeCompare(a.date)).slice(0, days);
  } catch {
    return [];
  }
}

export interface PaceStats {
  dailyAvgCost: number;
  projectedMonthlyCost: number;
  daysRemaining: number | null;
  monthSpent: number;
}

export async function getPaceStats(budgetUsd?: number): Promise<PaceStats> {
  const usage = await getUsageStats(7);
  const weekCost = usage.reduce((sum, d) => sum + (d.totalCost || 0), 0);
  const daysWithData = usage.length || 1;
  const dailyAvgCost = weekCost / daysWithData;
  const projectedMonthlyCost = dailyAvgCost * 30;

  const allUsage = await getUsageStats(30);
  const monthSpent = allUsage.reduce((sum, d) => sum + (d.totalCost || 0), 0);

  let daysRemaining: number | null = null;
  if (budgetUsd && budgetUsd > 0 && dailyAvgCost > 0) {
    const remaining = Math.max(0, budgetUsd - monthSpent);
    daysRemaining = Math.floor(remaining / dailyAvgCost);
  }

  return { dailyAvgCost, projectedMonthlyCost, daysRemaining, monthSpent };
}

export async function cleanupOldUsage(): Promise<number> {
  let removed = 0;
  try {
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - MAX_DAYS);
    const cutoffStr = cutoff.toISOString().slice(0, 10);

    const all = await state.list<DailyUsage>({ scope: SCOPE });
    for (const entry of all) {
      if (entry.date < cutoffStr) {
        await state.delete({ scope: SCOPE, key: entry._key });
        removed++;
      }
    }
  } catch (e) {
    logger.error("Failed to cleanup old usage", {
      error: (e as Error)?.message,
    });
  }
  return removed;
}

