interface ApiStatusResult {
  indicator: string;
  description: string;
  updatedAt: string;
}

const VALID_INDICATORS = new Set(["none", "minor", "major", "critical"]);
let apiStatusCache: { data: ApiStatusResult; fetchedAt: number } | null = null;
const API_STATUS_CACHE_TTL = 60_000;

async function handleApiStatus(
  _req: IncomingMessage,
  res: ServerResponse,
): Promise<void> {
  const now = Date.now();
  if (apiStatusCache && now - apiStatusCache.fetchedAt < API_STATUS_CACHE_TTL) {
    res.writeHead(200, {
      ...corsHeaders(),
      "content-type": "application/json",
    });
    res.end(JSON.stringify(apiStatusCache.data));
    return;
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 3000);
  try {
    const response = await fetch(
      "https://status.anthropic.com/api/v2/status.json",
      {
        signal: controller.signal,
      },
    );
    const json = (await response.json()) as {
      status?: { indicator?: string; description?: string };
      page?: { updated_at?: string };
    };
    const rawIndicator = json.status?.indicator ?? "";
    const result: ApiStatusResult = {
      indicator: VALID_INDICATORS.has(rawIndicator) ? rawIndicator : "unknown",
      description: json.status?.description || "Unable to determine",
      updatedAt: json.page?.updated_at || new Date().toISOString(),
    };
    apiStatusCache = { data: result, fetchedAt: now };
    res.writeHead(200, {
      ...corsHeaders(),
      "content-type": "application/json",
    });
    res.end(JSON.stringify(result));
  } catch {
    const fallback: ApiStatusResult = {
      indicator: "unknown",
      description: "Unable to check",
      updatedAt: new Date().toISOString(),
    };
    res.writeHead(200, {
      ...corsHeaders(),
      "content-type": "application/json",
    });
    res.end(JSON.stringify(fallback));
  } finally {
    clearTimeout(timeout);
  }
}

let server: Server | null = null;

export function startProxy(): Promise<void> {
  unsubEngineState = onEngineConnectionStateChange((s) => {
    engineConnected = s === "connected";
    engineConnectionState = s;
    logger.info("Engine connection state changed", { state: s });
  });

  if (!API_TOKEN) {
    logger.warn("No TAILCLAUDE_TOKEN set — proxy is open to all tailnet peers");
  }

  return new Promise((resolve, reject) => {
    server = createServer((req, res) => {
      const url = req.url || "";
      const method = req.method || "GET";

      if (method === "GET" && (url === "/" || url === "")) {
        const html = loadHtml();
        res.writeHead(200, {
          "content-type": "text/html; charset=utf-8",
          ...corsHeaders(),
          "cache-control": isProduction
            ? "public, max-age=300"
            : "no-cache, no-store",
        });
        res.end(html);
        return;
      }

      if (method === "OPTIONS") {
        res.writeHead(204, {
          ...corsHeaders(),
          "access-control-max-age": "86400",
        });
        res.end();
        return;
      }

      if (!checkAuth(req, res)) return;

      const parsedUrl = new URL(url, `http://${req.headers.host}`);
      const pathname = parsedUrl.pathname;

      if (method === "GET" && pathname === "/health") {
        handleHealth(req, res).catch(() => {
          if (!res.headersSent) {
            jsonError(res, 500, "Health check failed");
          }
        });
        return;
      }

      if (method === "POST" && pathname === "/chat") {
        handleChat(req, res);
        return;
      }

      if (method === "POST" && pathname === "/chat/stop") {
        handleStopChat(req, res);
        return;
      }

      if (method === "GET" && pathname === "/sessions") {
        handleSessions(req, res).catch(() => {
          if (!res.headersSent) {
            jsonError(res, 500, "Failed to list sessions");
          }
        });
        return;
      }

      const sessionMatch =
        method === "GET" && pathname.match(/^\/sessions\/([a-f0-9-]{36})$/);
      if (sessionMatch) {
        handleSessionHistory(req, res, sessionMatch[1]).catch(() => {
          if (!res.headersSent) {
            jsonError(res, 500, "Failed to load session");
          }
        });
        return;
      }

      if (method === "GET" && pathname === "/qr") {
        handleQr(req, res).catch(() => {
          if (!res.headersSent) {
            jsonError(res, 500, "Failed to generate QR");
          }
        });
        return;
      }

      if (method === "GET" && pathname === "/settings") {
        handleSettings(req, res).catch(() => {
          if (!res.headersSent) {
            jsonError(res, 500, "Failed to fetch settings");
          }
        });
        return;
      }

      if (method === "GET" && pathname === "/activity") {
        handleActivitySSE(res);
        return;
      }

      if (method === "GET" && pathname === "/usage") {
        handleUsage(req, res).catch(() => {
          if (!res.headersSent) jsonError(res, 500, "Failed to fetch usage");
        });
        return;
      }

      if (method === "GET" && pathname === "/chat/active") {
        handleChatActive(req, res);
        return;
      }

      const replayMatch =
        method === "GET" && pathname.match(/^\/chat\/replay\/([a-f0-9-]{36})$/);
      if (replayMatch) {
        handleChatReplay(req, res, replayMatch[1]).catch(() => {
          if (!res.headersSent) jsonError(res, 500, "Failed to replay chat");
        });
        return;
      }

      if (method === "GET" && pathname === "/metrics") {
        handleMetricsTimeline(req, res).catch(() => {
          if (!res.headersSent) jsonError(res, 500, "Failed to fetch metrics");
        });
        return;
      }

      if (method === "GET" && pathname === "/traces") {
        handleTraces(req, res).catch(() => {
          if (!res.headersSent) jsonError(res, 500, "Failed to fetch traces");
        });
        return;
      }

      if (method === "GET" && pathname === "/api-status") {
        handleApiStatus(req, res).catch(() => {
          if (!res.headersSent)
            jsonError(res, 500, "Failed to check API status");
        });
        return;
      }

      const proxyReq = httpRequest(
        {
          hostname: "127.0.0.1",
          port: III_PORT,
          path: url,
          method,
          headers: req.headers,
        },
        (proxyRes) => {
          res.writeHead(proxyRes.statusCode ?? 502, proxyRes.headers);
          proxyRes.pipe(res, { end: true });
        },
      );

      proxyReq.on("error", () => {
        res.writeHead(502, { "content-type": "application/json" });
        res.end(JSON.stringify({ error: "iii engine unavailable" }));
      });

      req.pipe(proxyReq, { end: true });
    });

    server.listen(PROXY_PORT, "0.0.0.0", () => {
      logger.info("UI proxy listening", { port: PROXY_PORT });
      resolve();
    });

    server.on("error", reject);
  });
}

export function stopProxy(): Promise<void> {
  return new Promise((resolve) => {
    metricsCollector.stopMonitoring();
    if (unsubEngineState) {
      unsubEngineState();
      unsubEngineState = undefined;
    }
    if (server) {
      server.close(() => resolve());
    } else {
      resolve();
    }
  });
}

import { execFile } from "node:child_process";
import { Logger } from "iii-sdk";
import { stopProxy } from "../proxy.js";

const TAILSCALE_CLI =
  process.platform === "darwin"
    ? "/Applications/Tailscale.app/Contents/MacOS/Tailscale"
    : "tailscale";

const SHUTDOWN_TIMEOUT_MS = 5_000;
const logger = new Logger(undefined, "tailclaude-shutdown");

let shuttingDown = false;

async function unpublishTailscale(): Promise<void> {
  return new Promise((resolve) => {
    execFile(
      TAILSCALE_CLI,
      ["serve", "--https=443", "off"],
      { timeout: 10_000 },
      (err, _stdout, stderr) => {
        if (err) {
          logger.error("Tailscale cleanup error", { error: stderr || err.message });
        } else {
          logger.info("Tailscale serve unpublished (HTTPS 443)");
        }
        resolve();
      },
    );
  });
}

async function shutdown(signal: string): Promise<void> {
  if (shuttingDown) return;
  shuttingDown = true;

  logger.info("Shutting down TailClaude", { signal });

  const forceExit = setTimeout(() => {
    logger.error("Graceful shutdown timed out, forcing exit");
    process.exit(1);
  }, SHUTDOWN_TIMEOUT_MS);
  forceExit.unref();

  try {
    await Promise.all([unpublishTailscale(), stopProxy()]);
  } catch {
    // best-effort cleanup
  }

  clearTimeout(forceExit);
  process.exit(0);
}

export function registerShutdownHandlers(): void {
  process.once("SIGINT", () => shutdown("SIGINT"));
  process.once("SIGTERM", () => shutdown("SIGTERM"));
  logger.info("Shutdown handlers registered", { signals: ["SIGINT", "SIGTERM"] });
}

import type { ApiRequest, ApiResponse } from "iii-sdk";
import { getEngineConnectionState } from "../iii.js";
import { state } from "../state.js";
import { getSessionIndex } from "../sessions.js";
import { metricsCollector } from "../metrics.js";

type TailscaleState = {
  ip: string | null;
  connectedAt: string | null;
  error?: string;
};

type PublishedState = {
  url: string;
  publishedAt: string;
};

export const handleHealth = async (_req: ApiRequest): Promise<ApiResponse> => {
  let tailscale: TailscaleState | null = null;
  let published: PublishedState | null = null;
  let activeChats: unknown[] = [];
  let sessionCount = 0;

  try {
    [tailscale, published, activeChats, sessionCount] = await Promise.all([
      state.get<TailscaleState>({ scope: "config", key: "tailscale" }),
      state.get<PublishedState>({ scope: "config", key: "published_url" }),
      state.list({ scope: "active_chats" }),
      getSessionIndex().then((s) => s.length),
    ]);
  } catch {
    // state store unavailable
  }

  const connectionState = getEngineConnectionState();
  const workerMetrics = metricsCollector.collect();

  return {
    status_code: 200,
    headers: { "content-type": "application/json" },
    body: {
      status: "ok",
      service: "tailclaude",
      timestamp: new Date().toISOString(),
      engine: {
        connected: connectionState === "connected",
        state: connectionState,
      },
      tailscale: {
        connected: !!tailscale?.ip,
        ip: tailscale?.ip ?? null,
        connectedAt: tailscale?.connectedAt ?? null,
      },
      publishedUrl: published?.url ?? null,
      sessions: {
        active: activeChats.length,
        total: sessionCount,
      },
      worker: {
        memory_heap_used: workerMetrics.memory_heap_used,
        memory_rss: workerMetrics.memory_rss,
        cpu_percent: workerMetrics.cpu_percent,
        event_loop_lag_ms: workerMetrics.event_loop_lag_ms,
        uptime_seconds: workerMetrics.uptime_seconds,
      },
    },
  };
};

import type { Context } from "iii-sdk";
import { Logger } from "iii-sdk";
import { state } from "../state.js";
import { emit } from "../hooks.js";
import { cleanStaleSessionIndex } from "../sessions.js";
import { cleanupStaleStreams } from "../streams.js";

type Session = {
  id: string;
  model: string;
  createdAt: string;
  lastUsed: string;
  messageCount: number;
};

type ActiveChat = {
  sessionId: string | null;
  model: string;
  startedAt: string;
  pid: number | null;
};

const MAX_AGE_MS = 24 * 60 * 60 * 1000;
const logger = new Logger(undefined, "tailclaude-cleanup");

function isProcessRunning(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

export const handleCleanup = async (_ctx: Context): Promise<void> => {
  let removedSessions = 0;
  let removedActiveChats = 0;
  let removedSessionIndex = 0;
  let removedStreams = 0;

  let sessions: Session[] = [];
  try {
    sessions = await state.list<Session>({ scope: "sessions" });
  } catch (err) {
    logger.warn("Failed to list sessions for cleanup", {
      error: (err as Error)?.message,
    });
  }
  const now = Date.now();

  for (const session of sessions) {
    const age = now - new Date(session.lastUsed).getTime();
    if (age > MAX_AGE_MS) {
      await state.delete({ scope: "sessions", key: session.id });
      removedSessions++;
    }
  }

  try {
    const activeChats = await state.list<
      ActiveChat & { key?: string; id?: string }
    >({
      scope: "active_chats",
    });
    for (const chat of activeChats) {
      const key = chat.key || chat.id || "";
      if (!key) continue;
      if (chat.pid && !isProcessRunning(chat.pid)) {
        await state.delete({ scope: "active_chats", key });
        removedActiveChats++;
      }
    }
  } catch {
    // active_chats scope may not exist yet
  }

  try {
    removedSessionIndex = await cleanStaleSessionIndex();
  } catch {
    // session index cleanup failed
  }

  try {
    removedStreams = cleanupStaleStreams();
  } catch (err) {
    logger.error("Failed to cleanup stale streams", {
      error: (err as Error)?.message,
    });
  }

  const total =
    removedSessions + removedActiveChats + removedSessionIndex + removedStreams;

  if (total > 0) {
    logger.info("Cleanup completed", {
      removedSessions,
      removedActiveChats,
      removedSessionIndex,
      removedStreams,
    });
  }

  try {
    await emit("cleanup::completed", {
      removedSessions,
      removedActiveChats,
      removedSessionIndex,
      removedStreams,
      total,
    });
  } catch (err) {
    logger.error("Failed to emit cleanup::completed", {
      error: (err as Error)?.message,
    });
  }
};
